async function clients() { const rows=await api("/clientes"); if(!rows.length){setContent("Clientes",table(rows));return;} setContent("Clientes",`<article class="panel"><h2>Directorio compacto</h2><label>Cliente<select id="client-selector">${rows.map((x)=>`<option value="${x.id_persona}">#${x.id_persona} · ${escapeHtml(x.nombre)}</option>`).join("")}</select></label></article><div id="client-detail" class="result"></div>`); const load=async()=>{ const id=$("#client-selector").value; const client=await api(`/clientes/${id}`); $("#client-detail").innerHTML=clientDetailHtml(client); $("#edit-client")?.addEventListener("submit",async(event)=>{event.preventDefault();const x=fields(event.target);try{await api(`/clientes/${id}`,{method:"PATCH",body:JSON.stringify({names:x.names,surnames:x.surnames||null,phone:x.phone||null,document:x.document||null,usual_address:x.usual_address||null})});notice("Ficha actualizada");await load();}catch(error){notice(error.message,true);}}); $("#wholesale-client")?.addEventListener("submit",async(event)=>{event.preventDefault();const x=fields(event.target);try{await api(`/clientes/${id}/condicion-mayorista`,{method:"POST",body:JSON.stringify({enabled:x.enabled==="true",reason:x.reason})});notice("Condición comercial registrada");await load();}catch(error){notice(error.message,true);}}); }; $("#client-selector").addEventListener("change",()=>load().catch((error)=>notice(error.message,true))); await load(); }

