async function employees() {
  const [rows, roles] = await Promise.all([api("/empleados"), api("/empleados/roles")]);
  const roleOptions = options(roles,"id_rol","nombre");
  setContent("Empleados y roles", `${employeeTable(rows)}<p class="muted result">“Solicitud aceptada” confirma que Supabase recibió la petición. La entrega del correo depende del proveedor. Si la redirección usa 127.0.0.1, el enlace sólo abre en la computadora que aloja FastAPI.</p><div class="two-columns result"><article class="panel"><h2>Invitar empleado</h2><form id="invite-employee" class="form-grid"><label>Nombres<input name="names" required></label><label>Apellidos<input name="surnames"></label><label>Correo<input name="email" type="email" required></label><label>Teléfono<input name="phone"></label><label>Documento<input name="document"></label><label>Rol<select name="role_id">${roleOptions}</select></label><button>Solicitar invitación segura</button></form></article><article class="panel"><h2>Cambiar rol</h2><form id="assign-role" class="form-grid"><label>Empleado<select name="employee_id">${rows.map((x) => `<option value="${x.id_persona}">${escapeHtml(x.nombre)} · ${escapeHtml(x.codigo_empleado)}</option>`).join("")}</select></label><label>Rol<select name="role_id">${roleOptions}</select></label><button>Asignar</button></form></article></div>`);
  $("#invite-employee").addEventListener("submit", async (event) => { event.preventDefault(); const x=fields(event.target); try { await api("/empleados/invitaciones", { method:"POST", body:JSON.stringify({ ...x, role_id:+x.role_id, capacity:10, surnames:x.surnames || null, phone:x.phone || null, document:x.document || null }) }); notice("Supabase aceptó la solicitud; la activación y entrega del correo siguen pendientes"); await employees(); } catch(error){ notice(error.message,true); } });
  $("#assign-role").addEventListener("submit", async (event) => { event.preventDefault(); const x=fields(event.target); try { await api(`/empleados/${x.employee_id}/rol`, { method:"PUT", body:JSON.stringify({ role_id:+x.role_id }) }); notice("Rol actualizado; será efectivo en la próxima consulta"); await employees(); } catch(error){ notice(error.message,true); } });
  document.querySelectorAll(".resend-invitation").forEach((button) => button.addEventListener("click", async () => { button.disabled=true; try { await api(`/empleados/${button.dataset.employeeId}/reenviar-invitacion`, { method:"POST" }); notice("Supabase aceptó la solicitud de un enlace nuevo; la entrega sigue pendiente"); await employees(); } catch(error) { notice(error.message,true); button.disabled=false; } }));
}

async function designs() {
  const rows = await api("/pedidos");
  const summaries = await Promise.all(rows.map((x) => api(`/pedidos/${x.id_pedido}/operacion`)));
  const orderOptions=rows.map((x) => `<option value="${x.id_pedido}">${escapeHtml(x.codigo_pedido)} · ${escapeHtml(x.estado)}</option>`).join("");
  const actionMap = { INICIAR_PRODUCCION:["start","Iniciar producción"], CONSUMIR_RESERVAS:["consume","Consumir reservas"], COMPLETAR_PRODUCCION:["finish","Completar producción"] };
  const available = summaries.flatMap((summary) => summary.produccion.acciones_permitidas.filter((code) => permitted(productionPermissions[code])).map((code) => ({ id:summary.pedido.id_pedido, pedido:summary.pedido.codigo_pedido, code, action:actionMap[code][0], label:actionMap[code][1] })));
  const productionPanel = available.length ? `<article class="panel"><h2>Operación de producción</h2><form id="production-action" class="form-grid"><label>Acción permitida<select name="operation">${available.map((x) => `<option value="${x.id}:${x.action}">${escapeHtml(x.pedido)} · ${escapeHtml(x.label)}</option>`).join("")}</select></label><button>Ejecutar</button></form></article>` : '<article class="panel"><h2>Operación de producción</h2><p class="muted">No hay acciones de producción autorizadas en este momento.</p></article>';
  const operationalState = table(summaries.map((x) => ({ pedido:x.pedido.codigo_pedido, estado:x.pedido.estado, siguiente:x.siguiente_accion, condición:x.produccion.mensaje })));
  setContent("Diseños", `${table(rows)}<div class="two-columns result"><article class="panel"><h2>Nueva versión privada</h2><form id="upload-design" class="form-grid"><label>Pedido<select name="order_id">${orderOptions}</select></label><label>Línea<input name="line" type="number" min="1" value="1" required></label><label>Archivo<input name="file" type="file" accept="image/png,image/jpeg,application/pdf" required></label><button>Subir</button></form></article><article class="panel"><h2>Revisar versiones</h2><form id="load-designs" class="form-grid"><label>Pedido<select name="order_id">${orderOptions}</select></label><label>Línea<input name="line" type="number" min="1" value="1" required></label><button>Consultar versiones</button></form></article>${productionPanel}</div><h2>Estado operativo</h2>${operationalState}<div id="design-versions" class="result"></div>`);
  $("#upload-design").addEventListener("submit", async (event) => { event.preventDefault(); const x=new FormData(event.target); const order=x.get("order_id"), line=x.get("line"); x.delete("order_id"); x.delete("line"); try { await api(`/disenos/pedidos/${order}/lineas/${line}/versiones`, { method:"POST", body:x }); notice("Versión de diseño almacenada"); } catch(error){ notice(error.message,true); } });
  $("#load-designs").addEventListener("submit", async (event) => { event.preventDefault(); const x=fields(event.target); try { const versions=await api(`/disenos/pedidos/${x.order_id}/lineas/${x.line}/versiones`); $("#design-versions").innerHTML=`${table(versions)}${versions.length ? `<article class="panel result"><form id="design-decision" class="form-grid inline"><input type="hidden" name="order_id" value="${x.order_id}"><input type="hidden" name="line" value="${x.line}"><label>Versión<select name="version">${versions.map((v) => `<option value="${v.numero_version}">Versión ${v.numero_version} · ${escapeHtml(v.nombre_archivo)}</option>`).join("")}</select></label><label>Decisión<select name="approved"><option value="true">Aprobar</option><option value="false">Rechazar</option></select></label><button>Registrar decisión</button></form></article>` : ""}`; $("#design-decision")?.addEventListener("submit", async (decisionEvent) => { decisionEvent.preventDefault(); const d=fields(decisionEvent.target); try { await api(`/disenos/pedidos/${d.order_id}/lineas/${d.line}/versiones/${d.version}/decision`, { method:"POST", body:JSON.stringify({ approved:d.approved === "true", medium:"PORTAL" }) }); notice("Decisión de diseño registrada"); } catch(error){ notice(error.message,true); } }); } catch(error){ notice(error.message,true); } });
  $("#production-action")?.addEventListener("submit", async (event) => { event.preventDefault(); const x=fields(event.target); const [orderId,action]=x.operation.split(":"); const paths={ start:`/produccion/pedidos/${orderId}/iniciar`, consume:`/inventario/pedidos/${orderId}/consumir`, finish:`/produccion/pedidos/${orderId}/completar` }; try { await api(paths[action],{ method:"POST" }); notice("Operación de producción completada"); await designs(); } catch(error){ notice(error.message,true); } });
}
async function profile() { const data=await api("/perfil"); setContent("Mi perfil",`<div class="two-columns"><article class="panel"><h2>Datos personales</h2><form id="profile-form" class="form-grid"><label>Nombres<input name="names" value="${escapeHtml(data.nombres)}" required></label><label>Apellidos<input name="surnames" value="${escapeHtml(data.apellidos)}"></label><label>Teléfono<input name="phone" value="${escapeHtml(data.telefono)}"></label><label>Documento<input name="document" value="${escapeHtml(data.documento)}"></label><label>Dirección habitual<textarea name="usual_address">${escapeHtml(data.direccion_habitual)}</textarea></label><button>Guardar mis datos</button></form></article><article class="panel"><h2>Seguridad e identidad</h2><dl><dt>Correo verificado</dt><dd>${escapeHtml(data.correo)}</dd><dt>Perfil</dt><dd>${escapeHtml(data.tipo_perfil)}</dd><dt>Roles</dt><dd>${escapeHtml(data.roles.join(", ") || "Cliente")}</dd><dt>Condición comercial</dt><dd>${escapeHtml(data.condicion_comercial || "No aplica")}</dd></dl><form id="email-change" class="form-grid"><label>Nuevo correo<input name="new_email" type="email" required></label><button>Solicitar cambio verificado</button></form><button id="sync-email" type="button" class="secondary result">Sincronizar correo ya confirmado</button><p class="muted">Los roles, permisos, UUID y condición mayorista sólo pueden cambiarse mediante operaciones administrativas autorizadas.</p></article></div>`); $("#profile-form").addEventListener("submit",async(event)=>{event.preventDefault();const x=fields(event.target);try{await api("/perfil",{method:"PATCH",body:JSON.stringify({names:x.names,surnames:x.surnames||null,phone:x.phone||null,document:x.document||null,usual_address:x.usual_address||null})});notice("Perfil actualizado");await profile();}catch(error){notice(error.message,true);}}); $("#email-change").addEventListener("submit",async(event)=>{event.preventDefault();const x=fields(event.target);try{await api("/perfil/correo/solicitar",{method:"POST",body:JSON.stringify({new_email:x.new_email})});notice("Supabase aceptó la solicitud. Confirma el nuevo correo y vuelve a iniciar sesión.");}catch(error){notice(error.message,true);}}); $("#sync-email").addEventListener("click",async()=>{try{await api("/perfil/correo/sincronizar",{method:"POST"});notice("Correo verificado sincronizado");await profile();}catch(error){notice(error.message,true);}}); }

const loaders = { summary,orders,quotes,payments,catalog,inventory,purchases,providers,losses,reports,employees,clients,designs,tracking,profile };
async function navigate(view) {
  const item = (menus[scope] || []).find((entry) => entry[0] === view && (!entry[2] || permitted(entry[2])));
  if (!item) { location.assign(expectedDashboard); return; }
  history.replaceState(null,"",`${location.pathname}?view=${view}`);
  document.querySelectorAll("#menu a").forEach((link) => link.classList.toggle("active",link.dataset.view===view));
  try { await loaders[view](); } catch(error) { setContent(item[1],""); notice(error.message,true); }
}
async function start() {
  if (!accessToken()) { location.assign("/app/#acceso"); return; }
  try {
    identity = await AuthSession.verifyIdentity(
      () => api("/auth/me"),
      { retries: 2, sleep: (delay) => new Promise((resolve) => setTimeout(resolve, delay)) },
    );
  } catch (error) {
    const outcome = AuthSession.classifyIdentityError(error);
    if (outcome.clearSession) {
      sessionStorage.removeItem("s2r_access_token");
      location.assign("/app/#acceso");
      return;
    }
    notice(outcome.message, true);
    return;
  }
  if (identity.dashboard_inicial !== expectedDashboard) { location.assign(identity.dashboard_inicial); return; }
  $("#user-name").textContent=identity.nombre;
  $("#user-role").textContent=identity.roles.join(" · ") || identity.tipo_perfil;
  $("#account-state").textContent=identity.estado_cuenta;
  const available=(menus[scope] || []).filter((entry) => !entry[2] || permitted(entry[2]));
  $("#menu").innerHTML=available.map((entry) => `<a href="?view=${entry[0]}" data-view="${entry[0]}">${escapeHtml(entry[1])}</a>`).join("");
  $("#menu").addEventListener("click", (event) => { const link=event.target.closest("a[data-view]"); if(link){ event.preventDefault(); navigate(link.dataset.view); } });
  const requested=new URLSearchParams(location.search).get("view");
  await navigate(available.some((entry) => entry[0]===requested) ? requested : available[0][0]);
}
$("#logout").addEventListener("click", () => { sessionStorage.removeItem("s2r_access_token"); location.assign("/app/"); });
start();
